/* @lc app=leetcode id=3859 lang=kotlin */ class Solution { fun msAdd(ms: java.util.TreeMap<Int, Int>, q: Int) = ms.merge(q, 1) { a, b -> a + b } fun msDel(ms: java.util.TreeMap<Int, Int>, q: Int) = ms.merge(q, -1) { a, b -> a + b }.let { if (it == 0) ms.remove(q) } fun countSubarrays(nums: IntArray, k: Int, m: Int): Long = IntArray(100001).let { c1 -> IntArray(100001).let { c3 -> Array(100001) { ArrayList<Int>() }.let { pos -> IntArray(100001) { -1 }.let { qv -> java.util.TreeMap<Int, Int>().let { ms -> IntArray(2).let { ds -> nums.indices.fold(Triple(0, 0, 0L)) { (a0, b0, ans), r -> nums[r].let { v -> pos[v].add(r).let { (if (pos[v].size >= m) pos[v][pos[v].size - m] else -1).let { nq -> (if (c3[v] > 0) msDel(ms, qv[v]) else Unit).let { c3.set(v, c3[v] + 1).let { (if (c3[v] == 1) ds.set(1, ds[1] + 1) else Unit).let { qv.set(v, nq).let { msAdd(ms, nq).let { c1.set(v, c1[v] + 1).let { (if (c1[v] == 1) ds.set(0, ds[0] + 1) else Unit).let { generateSequence(a0) { aa -> if (ds[0] > k) nums[aa].let { u -> c1.set(u, c1[u] - 1).let { if (c1[u] == 0) ds.set(0, ds[0] - 1) } }.let { aa + 1 } else null }.last().let { a1 -> generateSequence(b0) { bb -> if (bb < r && ds[1] - (if (c3[nums[bb]] == 1) 1 else 0) >= k) nums[bb].let { u -> c3.set(u, c3[u] - 1).let { if (c3[u] == 0) ds.set(1, ds[1] - 1).let { msDel(ms, qv[u]) } } }.let { bb + 1 } else null }.last().let { b1 -> Triple(a1, b1, ans + (if (ds[1] >= k) maxOf(0, minOf(b1, ms.firstKey()) - a1 + 1) else 0)) } } } } } } } } } } } } }.third } } } } } } }